package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod = 998244353
const maxN = 500010

var fact [maxN]int64

func pw(a, b int64) int64 {
	res := int64(1)
	for b > 0 {
		if b&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		b >>= 1
	}
	return res
}

func inv(a int64) int64 {
	return pw(a, mod-2)
}

func main() {
	fact[0] = 1
	for i := 1; i < maxN; i++ {
		fact[i] = fact[i-1] * int64(i) % mod
	}

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	nextInt := func() int64 {
		scanner.Scan()
		x := int64(0)
		for _, c := range scanner.Bytes() {
			x = x*10 + int64(c-'0')
		}
		return x
	}

	n := nextInt()
	k := nextInt()

	var ans int64
	for i := int64(1); i <= n-k+1; i++ {
		cnt := n / i
		if cnt < k {
			continue
		}
		sum := fact[cnt-1] * inv(fact[k-1]) % mod
		sum = sum * inv(fact[cnt-k]) % mod
		ans += sum
		ans %= mod
	}
	fmt.Println(ans)
}

