	// Precompute factorials
	f[0] = 1
	for i := 1; i < maxN; i++ {
		f[i] = (f[i-1] * int64(i)) % mod
	}

	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	// Read tt (number of test cases)
	if !scanner.Scan() {
		return
	}
	tt, _ := strconv.Atoi(scanner.Text())

	for t := 0; t < tt; t++ {
		// Read n, k
